from collections import deque
text='''0 5 0 0 0 0 0 5 0 0 5 0
0 5 0 0 0 5 5 5 0 5 5 0
5 5 5 0 0 5 0 5 5 5 0 0
0 0 5 5 5 5 0 5 0 5 5 0
0 0 0 5 0 0 0 5 0 0 5 0'''
g=[list(map(int,x.split())) for x in text.splitlines()];h,w=len(g),len(g[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if g[r][c] or (r,c) in seen:continue
  q=deque([(r,c)]); seen.add((r,c)); cells=[]
  while q:
   x,y=q.popleft(); cells.append((x,y))
   for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=a<h and 0<=b<w and g[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
  comps.append(cells)
print('components sizes/coordinates:')
for cells in comps:print(len(cells),cells)
print('min max',min(map(len,comps)),max(map(len,comps)))
for color,cells in [(7,min(comps,key=len)),(8,max(comps,key=len))]:
 for r,c in cells:g[r][c]=color
print('output dims',len(g),[len(row) for row in g]);print(g)
